def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.75
        return float(min(budget, base))

    highest_prev = 0.0
    eric_prev = None
    rich_alive = 0
    urgent_opp_count = 0

    for opp in alive_opps:
        if opp.get('budget', 0) > DAILY_SALARY:
            rich_alive += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 2:
            urgent_opp_count += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid')
        if bid is not None and bid > highest_prev:
            highest_prev = bid
        if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
            if bid is not None and bid > 0:
                eric_prev = bid

    pressure = highest_prev
    if eric_prev is not None:
        pressure = max(pressure, eric_prev)

    ample_supply = supply >= 24
    tight_supply = supply <= 18

    desperation = 0
    if hp <= 2:
        desperation += 2
    elif hp <= 4:
        desperation += 1
    if no_water_days >= 2:
        desperation += 2
    elif no_water_days >= 1:
        desperation += 1

    if desperation >= 3:
        bid = max(DAILY_SALARY * 0.95, pressure + 3.0)
    elif desperation == 2:
        bid = max(DAILY_SALARY * 0.8, pressure * 0.72 + 2.0)
    else:
        if ample_supply:
            bid = DAILY_SALARY * 0.28
        elif tight_supply:
            bid = max(DAILY_SALARY * 0.48, pressure * 0.55)
        else:
            bid = max(DAILY_SALARY * 0.38, pressure * 0.42)

    if rich_alive <= 1 and pressure >= 100:
        if desperation <= 1:
            bid = min(bid, DAILY_SALARY * 0.34)
        else:
            bid = max(bid, DAILY_SALARY * 0.78)

    if urgent_opp_count >= 2 and desperation == 0:
        bid = min(bid, DAILY_SALARY * 0.3)

    days_left = 11 - day
    reserve_target = max(0.0, days_left * DAILY_SALARY * 0.32)
    affordable = max(0.0, budget - reserve_target)

    if desperation >= 2:
        affordable = budget
    elif affordable < DAILY_SALARY * 0.2:
        affordable = min(budget, DAILY_SALARY * 0.25)

    final_bid = min(budget, affordable, bid)

    if desperation >= 2:
        final_bid = min(budget, max(final_bid, min(budget, DAILY_SALARY * 0.72)))

    if final_bid < 0:
        final_bid = 0.0

    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # Identify alive opponents and use yesterday trace to infer their aggression.
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    if not alive:
        # No competition: bid modestly to secure water.
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace.
    prev_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Baseline from observed aggressive bidders.
    if prev_bids:
        # Use upper quantile-ish behavior via max/mean mix.
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = DAILY_SALARY * 0.8
        avg_prev = DAILY_SALARY * 0.6

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0.0)
    no_water_days = my_status.get('no_water_days', 0)

    # Pressure increases when my hp is low or I'm close to running out.
    # supply affects how many water units are likely to be available in general.
    # We don't know exact allocation rule, so we adjust bid level heuristically.
    supply_factor = 1.0
    if supply <= float(WATER_REQ):
        supply_factor = 1.15
    elif supply >= float(MAX_SUPPLY):
        supply_factor = 0.95

    # Target bid: slightly above the strongest recent bidder if I'm not in danger.
    # If I'm in danger, bid closer to/above highest_prev.
    if hp <= 2 or no_water_days >= 2:
        target = max(highest_prev * 0.98, avg_prev * 1.05)
    elif hp <= 4:
        target = max(avg_prev * 1.03, highest_prev * 0.92)
    else:
        # Safe: still compete, but don't overspend.
        target = max(avg_prev * 1.00, highest_prev * 0.88)

    target *= supply_factor

    # Convert to feasible bid within budget.
    # Also keep a floor to ensure we don't underbid when others are aggressive.
    min_floor = DAILY_SALARY * 0.65
    bid = max(min_floor, target)

    # If budget is low, scale down but keep enough to contest.
    if bid > budget:
        # If very low budget, take a last-stand bid.
        if hp <= 2:
            bid = budget
        else:
            bid = max(0.0, budget * 0.85)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55
    bid = base_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.9:
            if my_hp <= 3:
                bid = DAILY_SALARY * 0.98
            elif my_hp <= 5:
                bid = max(base_bid, highest_prev_bid + 2.0)
            else:
                bid = max(base_bid, highest_prev_bid + 1.0)
        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            if my_hp <= 4:
                bid = max(base_bid, highest_prev_bid + 3.0)
            else:
                bid = max(base_bid, highest_prev_bid + 1.5)
        else:
            if my_hp <= 2:
                bid = DAILY_SALARY * 0.95
            elif my_hp <= 4:
                bid = DAILY_SALARY * 0.85
            else:
                bid = max(base_bid, highest_prev_bid + 1.0)
    else:
        if my_hp <= 2:
            bid = DAILY_SALARY * 0.95
        elif my_hp <= 4:
            bid = DAILY_SALARY * 0.85
        else:
            bid = base_bid

    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp <= 5:
            bid = max(bid, DAILY_SALARY * 0.95)
        elif my_hp <= 7:
            bid = max(bid, DAILY_SALARY * 0.8)
    elif remaining_days <= 4:
        if my_hp <= 4:
            bid = max(bid, DAILY_SALARY * 0.9)

    final_bid = min(bid, my_budget)

    if final_bid <= 0 and my_budget > 0:
        final_bid = 1.0
    elif final_bid <= 0 and my_budget <= 0:
        final_bid = 0.0

    return final_bid
